"""
    Return True if input is palindrome, False otherwise.

    Args:
       input(str): input to be checked if it is palindrome
    """
def is_palindrome(input: Any) -> object {
    if (len(input) <= 1) {
        return True;
    } else {
        first_char = input[0];
        last_char = input[-1];
        sub_input = input[1:-1];
        return ((first_char == last_char) and is_palindrome(sub_input));
    }
}

""" get the ratio of GC pairs to the total number of  pairs from a  DNA strings """
def get_frequency_GC_str(string: Any) -> object {
    GC = [];
    total = len(string);
    for i in string {
        if ((i == 'C') or (i == 'G')) {
            GC.append(1);
        }
    }
    return float((sum(GC) / total));
}

